use verus::prelude::*;

fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // The result has the same length as the input.
    ensures!(result.len() == arr.len());
    // For each index i, if min_val <= max_val then we clip arr[i] into [min_val, max_val],
    // otherwise we set result[i] = max_val.
    ensures!(
        forall(|i: usize| i < arr.len() ==>
            if min_val <= max_val {
                let ai = arr[i];
                // expected clipping behavior:
                let expected = if ai < min_val {
                    min_val
                } else if ai > max_val {
                    max_val
                } else {
                    ai
                };
                result[i] == expected
            } else {
                result[i] == max_val
            }
        )
    );

    if min_val <= max_val {
        // Clip each element into [min_val, max_val].
        arr.iter()
           .map(|&x| x.min(max_val).max(min_val))
           .collect()
    } else {
        // If min_val > max_val, fill the result with max_val.
        vec![max_val; arr.len()]
    }
}

